        "intents": {"research", "question", "compare", "summarize"},
    },
    "planning": {
        "domains": {"business", "software", "architecture", "general"},
        "actions": {"plan", "analyze"},
        "intents": {"plan", "analyze"},
    },
    "writing": {
        "domains": {"writing", "ai", "general", "software"},
        "actions": {"generate", "summarize"},
        "intents": {"create", "create_prompt", "generate", "summarize"},
    },
    "analysis": {
        "domains": {"business", "data", "science", "software"},
        "actions": {"analyze", "compare", "calculate"},
        "intents": {"analyze", "compare", "calculate"},
    },
    "general": {
        "domains": {"general", "music", "time", "writing"},
        "actions": {"chat", "recommend", "explain"},
        "intents": {"chat", "recommend", "datetime", "question"},
    },
}


class AgentSelector:
    def select(
        self,
        intent: dict[str, Any],
        understanding: dict[str, Any],
        *,
        context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        domain = str(understanding.get("domain") or intent.get("domain") or "general")
        action = str(understanding.get("required_action") or "")
        intent_name = str(intent.get("intent") or "")
        complexity = str(understanding.get("complexity") or "medium")

        scores: dict[str, float] = {}
        for name, caps in AGENT_CAPABILITIES.items():
            score = 0.0
            if domain in caps["domains"]:
                score += 2.0
            if action in caps["actions"]:
                score += 1.5
            if intent_name in caps["intents"]:
                score += 1.5
            if name == "general":
                score += 0.2  # soft prior
            if complexity == "high" and name in {"coding", "planning", "analysis", "research"}:
                score += 0.5
            scores[name] = score

        ranked = sorted(scores.items(), key=lambda x: x[1], reverse=True)
        primary = ranked[0][0] if ranked else "general"
        secondary = [n for n, s in ranked[1:3] if s >= 1.0]

        # Prompt creation often needs writing + coding together
        if intent_name == "create_prompt" and "writing" not in ([primary] + secondary):
            secondary.insert(0, "writing")

        return {
            "primary": primary,
            "secondary": secondary,
            "scores": scores,
            "team": [primary] + [s for s in secondary if s != primary],
        }

"""Internal plan: Understand → Solve → Verify → Respond."""
from __future__ import annotations

from typing import Any


class ReasoningEngine:
    def plan(
        self,
        understanding: dict[str, Any],
        intent: dict[str, Any],
        *,
        agents: dict[str, Any] | None = None,
        tools: dict[str, Any] | None = None,
        knowledge: dict[str, Any] | None = None,
        memory: dict[str, Any] | None = None,
        context: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        steps = [
            {
                "stage": "understand",
                "detail": understanding.get("goal") or intent.get("goal") or "",
            },
            {
                "stage": "solve",
                "detail": (
                    f"Use agents={agents.get('team') if agents else []} "
                    f"tools={tools.get('tools') if tools else []} "
                    f"sources={knowledge.get('sources') if knowledge else []}"
                ),
            },
            {
                "stage": "verify",
                "detail": "Check intent coverage, avoid hallucination, match format",
            },
            {
                "stage": "respond",
                "detail": f"Answer complexity={understanding.get('complexity')}",
            },
        ]
        return {
            "steps": steps,
            "interpretation": (context or {}).get("interpretation") or "",
            "memory_used": bool((memory or {}).get("used")),
            "knowledge_sources": (knowledge or {}).get("sources") or [],
            "agent_team": (agents or {}).get("team") or [],
            "tools": (tools or {}).get("tools") or [],
        }

"""Plan response style, then draft ONLY from real knowledge / reasoning / model."""
from __future__ import annotations

from typing import Any

from om_ai.core.intelligence.real_answer import build_real_answer, looks_like_static_reply


class ResponsePlanner:
    def plan_style(self, understanding: dict[str, Any], intent: dict[str, Any]) -> dict[str, Any]:
        complexity = str(understanding.get("complexity") or "medium")
        intent_name = str(intent.get("intent") or "")
        domain = str(understanding.get("domain") or "general")
        action = str(understanding.get("required_action") or "")

        if intent_name in {"chat"} or (complexity == "low" and action in {"chat", "answer"}):
            style = "short"
        elif domain in {"software", "architecture", "data"} and action in {
            "generate",
            "create",
            "debug",
        }:
            style = "technical_code"
        elif domain == "business" or action in {"plan", "analyze"}:
            style = "strategy"
        elif action in {"explain", "research", "summarize"} or domain == "science":
            style = "detailed"
        elif action == "recommend" or domain == "music":
            style = "recommendations"
        else:
            style = "balanced"

        return {
            "style": style,
            "tone": "helpful_direct",
            "ask_followup": style in {"recommendations", "technical_code", "strategy"},
        }

    def draft(
        self,
        question: str,
        understanding: dict[str, Any],
        intent: dict[str, Any],
        style: dict[str, Any],
        *,
        knowledge: dict[str, Any] | None = None,
        memory: dict[str, Any] | None = None,
        agents: dict[str, Any] | None = None,
        context: dict[str, Any] | None = None,
    ) -> str:
        """Real answer only — empty string means defer (no canned outline)."""
        packets = (knowledge or {}).get("packets") or []
        for p in packets:
            if p.get("source") == "facts" and p.get("texts"):
                t = str(p["texts"][0]).strip()
                if t and not looks_like_static_reply(t):
                    return t + "\n"
            if p.get("source") == "calendar_clock" and p.get("texts"):
                return str(p["texts"][0]).strip() + "\n"

        q = (question or "").strip()
        intent_name = str(intent.get("intent") or "")
        style_name = style.get("style") or "balanced"

        # Short greetings only
        qlow = q.lower()
        if intent_name == "chat" or style_name == "short":
            if qlow in {"hi", "hello", "hey", "yo", "sup"} or len(q.split()) <= 2 and qlow in {
                "hi",
                "hello",
                "hey",
            }:
                return "Hello — I'm OM. What would you like to work on?\n"

        prefer_coding = style_name == "technical_code" or intent_name in {
            "create",
            "code",
            "debug",
            "coding",
            "generate",
        } or any(
            w in qlow
            for w in ("code", "react", "python", "implement", "function", "api", "bug")
        )

        real = build_real_answer(
            q,
            prefer_coding=prefer_coding,
            knowledge_packets=list(packets),
        )
        if real:
            return real.strip() + "\n"
        # Memory snippets as last soft hint (must be substantial)
        for key in ("snippets", "hits", "items"):
            for s in (memory or {}).get(key) or []:
                t = str(s).strip() if not isinstance(s, dict) else str(s.get("text") or "").strip()
                if len(t) > 80 and not looks_like_static_reply(t):
                    return t + "\n"
        return ""

"""Retrieve relevant memory slices without topic-specific handlers."""
from __future__ import annotations

from typing import Any


class MemoryRetriever:
    def retrieve(
        self,
        question: str,
        *,
        conversation: list | None = None,
        project: Any = None,
        knowledge: Any = None,
        experience: Any = None,
        memory_context: dict | list | None = None,
    ) -> dict[str, Any]:
        hits: list[str] = []

        # Conversation snippets
        for item in (conversation or [])[-8:]:
            if isinstance(item, dict):
                text = str(item.get("content") or item.get("text") or "").strip()
            else:
                text = str(item).strip()
            if text and self._overlap(question, text) >= 0.08:
                hits.append(text[:400])

        # Generic memory_context
        if isinstance(memory_context, dict):
            relevant = memory_context.get("relevant") or memory_context.get("items") or []
            if isinstance(relevant, list):
                for r in relevant[:8]:
                    hits.append(str(r)[:400])
            elif relevant:
                hits.append(str(relevant)[:400])
        elif isinstance(memory_context, list):
            hits.extend(str(x)[:400] for x in memory_context[:8])

        if project:
            hits.append(f"project:{project}"[:400])
        if knowledge:
            if isinstance(knowledge, list):
                hits.extend(str(x)[:400] for x in knowledge[:5])
            else:
                hits.append(str(knowledge)[:400])
        if experience:
            hits.append(str(experience)[:400])

        # Deduplicate preserving order
        seen: set[str] = set()
        unique = []
        for h in hits:
            key = h.lower()
            if key in seen:
                continue
            seen.add(key)
            unique.append(h)

        return {
            "items": unique[:12],
            "count": len(unique),
            "used": bool(unique),
        }

    def _overlap(self, a: str, b: str) -> float:
        ta = set((a or "").lower().split())
        tb = set((b or "").lower().split())
        if not ta or not tb:
            return 0.0
        return len(ta & tb) / max(1, len(ta))

"""Decide which tools are needed — capability inference, not manual maps."""
from __future__ import annotations

import re
from typing import Any


class ToolSelector:
    def select(
        self,
        understanding: dict[str, Any],
        intent: dict[str, Any],
        *,
        knowledge: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        domain = str(understanding.get("domain") or "")
        action = str(understanding.get("required_action") or "")
        intent_name = str(intent.get("intent") or "")
        q = str(understanding.get("raw") or "").lower()

        tools: list[str] = []
        reasons: dict[str, str] = {}

        def need(name: str, why: str) -> None:
            if name not in tools:
                tools.append(name)
                reasons[name] = why

        if domain == "time" or intent_name in {"datetime", "date_request"}:
            # Never treat social "how was your date/day" as calendar
            if not re.search(
                r"\bhow\s+(was|is|are)\s+(your\s+)?(day|date)\b",
                q,
            ) and re.search(
                r"\b(today'?s?\s+date|current\s+date|what(?:'s|\s+is)\s+(?:the\s+)?date|"
                r"current\s+time|what(?:'s|\s+is)\s+the\s+time|what\s+day\s+is\s+it)\b",
                q,
            ):
                need("date", "temporal question")
        if action == "calculate" or any(x in q for x in ("calculate", "compute", "%", "sum")):
            need("calculator", "numeric computation")
        if action in {"research", "recommend"} or "latest" in q or "news" in q:
            need("web", "external or fresh info may help")
        if domain in {"software", "data", "architecture"} and action in {"generate", "debug", "create"}:
            need("code_execution", "validate or illustrate code")
        if "database" in q or "sql" in q or domain == "data":
            need("database", "data/schema work")
        if "file" in q or "readme" in q or action == "generate" and domain == "software":
            need("file", "file-oriented deliverable")

        # Knowledge packets already satisfy date — still list the tool
        if knowledge and any(p.get("source") == "calendar_clock" for p in knowledge.get("packets") or []):
            need("date", "clock knowledge attached")

        return {
            "tools": tools,
            "reasons": reasons,
            "needed": bool(tools),
        }

"""Conversation / project context before answering."""
from __future__ import annotations

from typing import Any


class ContextEngine:
    """Build a working context pack from messages + memory + preferences."""

    def build(
        self,
        question: str,
        *,
        messages: list[dict] | None = None,
        memory: dict | list | None = None,
        user_profile: dict | None = None,
        project: dict | str | None = None,
    ) -> dict[str, Any]:
        history = []
        for m in (messages or [])[-12:]:
            role = str(m.get("role") or "")
            content = str(m.get("content") or "").strip()
            if role in {"user", "assistant"} and content:
                history.append({"role": role, "content": content[:500]})

        recent_tasks = [
            h["content"]
            for h in history
            if h["role"] == "user"
        ][-5:]

        project_hint = ""
        if isinstance(project, dict):
            project_hint = str(project.get("name") or project.get("title") or project.get("id") or "")
        elif project:
            project_hint = str(project)

        # Soft inference: if prior turns mention a product, carry it forward
        blob = " ".join(recent_tasks).lower()
        if not project_hint:
            for hint in ("om ai", "react", "laravel", "fastapi", "cursor"):
                if hint in blob:
                    project_hint = hint
                    break

        prefs = {}
        if isinstance(user_profile, dict):
            prefs = {
                "technologies": user_profile.get("technologies") or [],
                "skills": user_profile.get("skills") or [],
                "preferences": user_profile.get("preferences") or {},
            }

        return {
            "question": question,
            "history": history,
            "recent_tasks": recent_tasks,
            "project_hint": project_hint,
            "project": project_hint,
            "user_profile": prefs,
            "memory_snapshot": memory if isinstance(memory, (dict, list)) else {},
            "interpretation": self._interpret(question, project_hint, recent_tasks),
        }

    def _interpret(self, question: str, project_hint: str, recent: list[str]) -> str:
        q = (question or "").lower()
        if "prompt" in q and project_hint:
            return f"Likely wants a development prompt related to {project_hint}."
        if recent and len(q.split()) <= 4:
            return f"Short follow-up; prior focus: {recent[-1][:80]}"
        return "Standalone request."

"""Quality gate — regenerate if score < threshold."""
from __future__ import annotations

import re
from typing import Any


class QualityEvaluator:
    def evaluate(
        self,
        question: str,
        answer: str,
        *,
        intent: dict[str, Any] | None = None,
        understanding: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        q = (question or "").strip()
        a = (answer or "").strip()
        intent = intent or {}
        understanding = understanding or {}
        issues: list[str] = []
        score = 100.0

        if not a:
            return {"score": 0.0, "passed": False, "issues": ["empty answer"], "needs_regenerate": True}

        # Intent coverage: answer should relate to question tokens
        q_tokens = set(re.findall(r"[a-z0-9]+", q.lower())) - {
            "a", "an", "the", "for", "to", "of", "and", "or", "is", "me", "my", "please",
        }
        a_low = a.lower()
        if q_tokens:
            hit = sum(1 for t in q_tokens if t in a_low)
            cover = hit / max(1, len(q_tokens))
            if cover < 0.15 and intent.get("intent") not in {"chat", "datetime"}:
                score -= 25
                issues.append("weak intent coverage")

        # Hallucination / pipeline chrome
        if re.search(r"(?i)\b(agents?:|intent:|self-critique|pipeline)\b", a):
            score -= 30
            issues.append("internal chrome leaked")

        if len(a) < 12:
            score -= 20
            issues.append("too short")

        # Completeness heuristics by style cues
        action = str(understanding.get("required_action") or "")
        if action in {"generate", "create"} and len(a) < 80:
            score -= 15
            issues.append("generation likely incomplete")

        if intent.get("intent") == "datetime" and not re.search(r"\d{4}|\b(monday|tuesday|wednesday|thursday|friday|saturday|sunday)\b", a, re.I):
            score -= 40
            issues.append("missing date content")

        score = max(0.0, min(100.0, score))
        passed = score >= 80.0
        return {
            "score": score,
            "passed": passed,
            "issues": issues,
            "needs_regenerate": not passed,
        }

    def regenerate(
        self,
        question: str,
        previous: str,
        evaluation: dict[str, Any],
        planner: Any,
        **kwargs: Any,
    ) -> str:
        """Second-pass draft with stricter balanced style."""
        understanding = kwargs.get("understanding") or {}
        intent = kwargs.get("intent") or {}
        style = {"style": "balanced", "tone": "helpful_direct", "ask_followup": True}
        draft = planner.draft(
            question,
            understanding,
            intent,
            style,
            knowledge=kwargs.get("knowledge"),
            memory=kwargs.get("memory"),
            agents=kwargs.get("agents"),
            context=kwargs.get("context"),
        )
        note = ""
        if evaluation.get("issues"):
            note = ""
        return (draft or previous or "").strip() + ("\n" if draft else "")

"""Route to knowledge *sources* by domain — never spawn MusicAgent/DateAgent/etc."""
from __future__ import annotations

from datetime import datetime
from typing import Any
from zoneinfo import ZoneInfo


# Domain → knowledge source labels (expandable registry, not if/else answer map)
DOMAIN_SOURCES: dict[str, list[str]] = {
    "music": ["recommendation_knowledge", "lifestyle_knowledge"],
    "software": ["code_knowledge", "documentation_knowledge", "architecture_patterns"],
    "ai": ["ai_research_knowledge", "prompt_knowledge"],
    "business": ["business_knowledge", "strategy_knowledge"],
    "science": ["science_knowledge", "explanatory_knowledge"],
    "time": ["calendar_clock"],
    "writing": ["writing_knowledge"],
    "data": ["data_knowledge", "schema_patterns"],
    "architecture": ["architecture_patterns", "system_design_knowledge"],
    "finance": ["finance_knowledge"],
    "general": ["general_knowledge", "conversation_knowledge"],
}


class KnowledgeRouter:
    def route(
        self,
        understanding: dict[str, Any],
        *,
        memory_hits: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        domain = str(understanding.get("domain") or "general")
        sources = list(DOMAIN_SOURCES.get(domain, DOMAIN_SOURCES["general"]))
        # Always allow general fallback source
        if "general_knowledge" not in sources:
            sources.append("general_knowledge")

        packets: list[dict[str, Any]] = []
        # Live tools as knowledge adapters (not domain agents)
        if domain == "time" or understanding.get("intent") == "datetime":
            packets.append(self._date_packet())

        if memory_hits and memory_hits.get("items"):
            packets.append(
                {
                    "source": "memory",
                    "texts": list(memory_hits.get("items") or [])[:6],
                }
            )

        # Fact lookup is a knowledge source, not a category handler
        try:
            from om_ai.knowledge.facts import lookup_fact

            hit = lookup_fact(str(understanding.get("raw") or ""))
            if hit and hit.get("answer"):
                packets.append(
                    {
                        "source": "facts",
                        "texts": [str(hit["answer"])],
                        "meta": hit,
                    }
                )
        except Exception:
            pass

        return {
            "domain": domain,
            "sources": sources,
            "packets": packets,
        }

    def _date_packet(self) -> dict[str, Any]:
        try:
            now = datetime.now(ZoneInfo("Asia/Kolkata"))
        except Exception:
            now = datetime.now().astimezone()
        return {
            "source": "calendar_clock",
            "texts": [
                f"Today's date is {now.strftime('%A, %d %B %Y')}.",
                f"Local time approximately {now.strftime('%H:%M %Z')}.".strip(),
            ],
        }

"""OM Human-like Conversation Engine — understand before answering."""
from __future__ import annotations

import re
from dataclasses import asdict, dataclass, field
from typing import Any


@dataclass
class ConversationState:
    language: str = "en"
    intent: str = "chat"
    emotion: str = "neutral"
    goal: str = ""
    technology: list[str] = field(default_factory=list)
    plan: list[str] = field(default_factory=list)
    needs_clarification: bool = False
    clarification: str = ""
    meta: dict[str, Any] = field(default_factory=dict)

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)


_TECH = re.compile(
    r"\b(react|next\.?js|vue|angular|svelte|fastapi|flask|django|laravel|python|typescript|"
    r"javascript|node|sql|postgres|mongodb|docker|kubernetes|swift|kotlin|"
    r"php|\.net|csharp|c#|golang| rust|java)\b",
    re.I,
)


def detect_language(text: str) -> str:
    t = text or ""
    if re.search(r"[\u0900-\u097F]", t):
        return "hi"
    if re.search(r"[\u0600-\u06FF]", t):
        return "ar"
    return "en"


def detect_emotion(text: str) -> str:
    t = (text or "").lower()
    if any(w in t for w in ("angry", "furious", "hate", "stupid", "useless", "गधा", "बेकार")):
        return "frustrated"
    if any(w in t for w in ("sad", "upset", "hurt", "lonely", "cry", "दुख")):
        return "sad"
    if any(w in t for w in ("thanks", "great", "awesome", "love", "खुश", "धन्यवाद")):
        return "positive"
    if any(w in t for w in ("urgent", "asap", "hurry", "critical", "broken", "crash")):
        return "urgent"
    if "?" in t or any(w in t for w in ("how", "what", "why", "explain")):
        return "curious"
    return "neutral"


def infer_technologies(text: str) -> list[str]:
    return sorted({m.group(0).lower() for m in _TECH.finditer(text or "")})


def classify_and_plan(
    text: str,
    *,
    messages: list[dict[str, Any]] | None = None,
    project_instructions: str = "",
    memory_snippets: list[str] | None = None,
) -> ConversationState:
    from om_ai.agent.intent import classify_intent
    from om_ai.cognitive import run_cognitive_pipeline

    cog = run_cognitive_pipeline(
        text,
        messages=messages,
        project_instructions=project_instructions,
        memory_snippets=memory_snippets,
    )
    work = (cog.corrected or text or "").strip()
    intent = classify_intent(work)

    state = ConversationState(
        language=cog.language,
        intent=cog.intent if cog.intent != "chat" else intent.value,
        emotion=cog.emotion,
        goal=cog.goal,
        technology=cog.technologies,
        plan=cog.plan,
        meta={
            "understanding": cog.meta.get("understanding", {}),
            "cognitive": cog.to_dict(),
            "audience": cog.audience,
            "ui_phases": cog.ui_phases,
        },
    )

    qlow = work.lower()
    definitional = bool(
        re.match(r"^\s*(what|who)\s+is\b", work, re.I)
        and not re.search(r"\b(create|make|build|implement)\b", work, re.I)
    )
    if definitional:
        state.intent = "knowledge"
        if not state.plan:
            state.plan = [
                "Retrieve knowledge/memory",
                "Reason and verify",
                "Answer clearly",
            ]
    elif intent.value == "coding" or cog.intent == "coding" or any(
        w in qlow for w in ("ui", "page", "signup", "login", "dashboard", "api", "code")
    ):
        state.intent = "coding" if intent.value == "chat" else intent.value
        if not state.technology and any(
            w in qlow for w in ("ui", "page", "signup", "login", "frontend", "react")
        ):
            state.technology = ["react"]
            state.clarification = "Assuming React for UI unless you specify another stack."
        if not state.plan:
            state.plan = [
                "Understand UI/API requirements",
                "Choose stack (inferred or stated)",
                "Produce files + code",
                "Note validation and next tests",
            ]
    elif intent.value in {"knowledge", "agent"}:
        if not state.plan:
            state.plan = [
                "Retrieve knowledge/memory",
                "Reason and verify",
                "Answer clearly",
            ]
    elif not state.plan:
        state.plan = [
            "Understand meaning",
            "Use memory + knowledge if relevant",
            "Reply naturally",
        ]
    return state


