"""Authentication, authorisation, RBAC and tenant context for OM AI."""
from __future__ import annotations

import json
import logging
import os
import uuid
import warnings
from contextvars import ContextVar
from dataclasses import dataclass, field
from typing import Optional

logger = logging.getLogger(__name__)

_ROLE_PERMISSIONS: dict[str, frozenset[str]] = {
    "admin": frozenset({
        "model.load", "model.generate", "agent.run", "memory.write",
        "knowledge.read", "knowledge.write", "admin.registry", "admin.tokens", "feedback.write",
        "tool.shell", "tool.openapi",
    }),
    "operator": frozenset({
        "model.load", "model.generate", "agent.run", "memory.write",
        "knowledge.read", "knowledge.write", "feedback.write", "tool.openapi", "admin.tokens",
    }),
    "agent": frozenset({
        "model.generate", "agent.run", "memory.write",
        "knowledge.read", "knowledge.write", "feedback.write", "tool.openapi", "admin.tokens",
    }),
    "viewer": frozenset({"model.generate", "knowledge.read"}),
}

VALID_ROLES: frozenset[str] = frozenset(_ROLE_PERMISSIONS)


class RBAC:
    def can(self, role: str, permission: str) -> bool:
        return permission in _ROLE_PERMISSIONS.get(role, frozenset())

    def require(self, role: str, permission: str) -> None:
        if not self.can(role, permission):
            raise PermissionError(f"Role '{role}' does not have permission '{permission}'")

    def permissions_for(self, role: str) -> frozenset[str]:
        return _ROLE_PERMISSIONS.get(role, frozenset())


rbac = RBAC()


@dataclass
class TenantContext:
    tenant_id: str = "default"
    actor: str = "anonymous"
    role: str = "viewer"
    request_id: str = field(default_factory=lambda: uuid.uuid4().hex)

    def has_permission(self, permission: str) -> bool:
        return rbac.can(self.role, permission)


_current_tenant: ContextVar[TenantContext] = ContextVar(
    "_current_tenant", default=TenantContext()
)


def get_current_tenant() -> TenantContext:
    return _current_tenant.get()


def set_current_tenant(ctx: TenantContext) -> None:
    _current_tenant.set(ctx)


def _parse_key_list(raw_env: str, *, default_role: str) -> dict[str, str]:
    """Parse comma-separated ``key`` or ``key:role`` entries into a key→role map."""
    keys: dict[str, str] = {}
    if not raw_env.strip():
        return keys
    fallback = default_role if default_role in VALID_ROLES else "viewer"
    for raw in raw_env.split(","):
        raw = raw.strip()
        if not raw:
            continue
        if ":" in raw:
            k, _, role = raw.partition(":")
            role = role.strip() if role.strip() in VALID_ROLES else fallback
            key = k.strip()
            if key:
                keys[key] = role
        else:
            keys[raw] = fallback
    return keys


def _load_api_keys() -> dict[str, str]:
    keys: dict[str, str] = {}
    # Standard bootstrap: key or key:role (bare key → operator).
    keys.update(_parse_key_list(os.getenv("OM_AI_API_KEYS", ""), default_role="operator"))
    # Optional admin-only list (bare key → admin). Supported so .env can keep
    # OM_AI_API_KEYS_ADMIN=…:admin without merging into OM_AI_API_KEYS.
    keys.update(_parse_key_list(os.getenv("OM_AI_API_KEYS_ADMIN", ""), default_role="admin"))
    keys_file = os.getenv("OM_AI_API_KEYS_FILE", "").strip()
    if keys_file and os.path.isfile(keys_file):
        with open(keys_file) as fh:
            data = json.load(fh)
        if isinstance(data, dict):
