    )
    checkpoint = (
        os.getenv("OM_MODEL_CHECKPOINT")
        or os.getenv("OM_AI_CHECKPOINT")
        or ""
    )
    if not checkpoint:
        from om_ai.backends.om_registry import pick_best_checkpoint

        best = pick_best_checkpoint(root)
        if best is not None:
            checkpoint = str(best)
