def normalize_provider_id(model: str | None) -> str | None:
    """Map request model aliases to a catalog id."""
    raw = (model or "").strip().lower()
    if not raw:
        return None
    aliases = {
        "om": "om",
        "om-1.0": "om",
        "om1.0": "om",
        "om_native": "om",
        "openai": "gpt",
        "gpt-4": "gpt",
        "gpt-4o": "gpt",
        "gpt-4o-mini": "gpt",
        "chatgpt": "gpt",
        "anthropic": "claude",
        "claude-3": "claude",
        "google": "gemini",
        "meta": "llama",
        "llama3": "llama",
        "groq": "llama",
    }
    if raw in LLM_CATALOG:
        return raw
    if raw in aliases:
        return aliases[raw]
    for pid, meta in LLM_CATALOG.items():
        name = str(meta.get("name") or "").lower()
        if raw == name or raw.startswith(pid):
            return pid
    return None


