            results.append(

                {

                    "agent":agent,

                    "score":score

                }

            )



        results.sort(

            key=lambda x:x["score"],

            reverse=True

        )


        selected=results[0]



        return {

            "agent":
                selected["agent"],

            "name":
                selected["agent"].name,

            "score":
                selected["score"]

        }

