"""
OM Performance Analyzer
"""





class PerformanceAnalyzer:



    def analyze(

        self,

        metrics,

        events

    ):



        counters = metrics.get(

            "counters",

            {}

        )



        return {


            "executions":

                counters.get(

                    "executions",

                    0

                ),


            "errors":

                counters.get(

                    "errors",

                    0

                ),


            "success_rate":

                self._success_rate(

                    counters

                )

        }




    def _success_rate(

        self,

        counters

    ):


        total=counters.get(

            "executions",

            0

        )


        errors=counters.get(

            "errors",

            0

        )


        if total==0:

            return 0



        return round(

            (total-errors)/total,

            3

        )

"""
OM Workflow Similarity Matcher
"""




class StrategyMatcher:



    def match(

        self,

        goal,

        memories

    ):


        goal_words=set(

            goal.lower().split()

        )


        results=[]



        for memory in memories:


            memory_goal=set(

                memory["goal"]

                .lower()

                .split()

            )



            similarity=len(

                goal_words & memory_goal

            ) / max(

                len(goal_words),

                1

            )



            results.append(

                {

                    "memory":

                        memory,

                    "similarity":

                        round(

                            similarity,

                            2

                        )

                }

            )



        results.sort(

            key=lambda x:

            x["similarity"],

            reverse=True

        )



        return results

