import subprocess
from pathlib import PurePosixPath
from typing import Any

from .base import Tool, ToolResult

# ─── Blocked path patterns ────────────────────────────────────────────────────

_BLOCKED_PATH_PREFIXES: tuple[str, ...] = (
    "/etc",
    "/var",
    "/root",
    "/proc",
    "/sys",
    "/dev",
    "/boot",
    "/usr/local/etc",
)

_DEFAULT_ALLOWLIST: frozenset[str] = frozenset({"echo", "pwd", "ls"})


def _contains_path_traversal(arg: str) -> bool:
    """Return True if the argument contains a path traversal pattern."""
    # Reject '..' segments (directory traversal)
    parts = PurePosixPath(arg).parts
    if ".." in parts:
        return True
    # Reject home-dir expansion
    if arg.startswith("~"):
        return True
    # Reject absolute paths into sensitive directories
    if arg.startswith("/"):
        for prefix in _BLOCKED_PATH_PREFIXES:
            if arg == prefix or arg.startswith(prefix + "/"):
                return True
    return False


class SafeShellTool(Tool):
    """
    Safe subprocess execution tool.

    Args:
        allowed: explicit set of permitted executable names (argv[0]).
                 Defaults to {'echo', 'pwd', 'ls'}.
        timeout: maximum execution time in seconds (default 15).
        extra_env: additional environment variables merged into the subprocess env.
    """

    name = "action.shell"
    description = (
        "Run an explicitly allow-listed local command without shell interpolation. "
        "Dangerous paths and directory traversal are blocked."
    )
    input_schema = {
        "type": "object",
        "properties": {
            "command": {"type": "string", "description": "Shell command string to parse and run"},
            "cwd": {"type": "string", "description": "Working directory (optional)"},
        },
        "required": ["command"],
    }
    risk_level = "medium"
    retry = 0

    def __init__(
        self,
        allowed: list[str] | frozenset[str] | None = None,
        timeout: int = 15,
        extra_env: dict[str, str] | None = None,
    ) -> None:
        self._allowed = frozenset(allowed) if allowed is not None else _DEFAULT_ALLOWLIST
        self.timeout = timeout
        self._extra_env = extra_env or {}

    def run(self, command: str = "", cwd: str | None = None, **kwargs: Any) -> ToolResult:
        if not command or not command.strip():
            return ToolResult(False, error="empty command")

        try:
            argv = shlex.split(command)
        except ValueError as exc:
            return ToolResult(False, error=f"command parse error: {exc}")

        if not argv:
            return ToolResult(False, error="empty command after parsing")

        # argv[0] allowlist check
        executable = os.path.basename(argv[0])
        if executable not in self._allowed:
            return ToolResult(
                False,
                error=(
                    f"command not in allowlist: {executable!r}. "
                    f"Allowed: {sorted(self._allowed)}"
                ),
            )

        # Path traversal check on all arguments
        for arg in argv[1:]:
            if _contains_path_traversal(arg):
                return ToolResult(
                    False,
                    error=f"blocked argument with path traversal pattern: {arg!r}",
                )

        # CWD sanity check
        if cwd and _contains_path_traversal(cwd):
            return ToolResult(False, error=f"blocked cwd with path traversal: {cwd!r}")

        # Build clean env
        env = {**os.environ, **self._extra_env}

        try:
            proc = subprocess.run(
                argv,
                cwd=cwd,
                capture_output=True,
                text=True,
                timeout=self.timeout,
                check=False,
                shell=False,   # NEVER use shell=True
                env=env,
            )
        except subprocess.TimeoutExpired:
            return ToolResult(False, error=f"command timed out after {self.timeout}s")
        except FileNotFoundError:
            return ToolResult(False, error=f"executable not found: {argv[0]!r}")
        except Exception as exc:
            return ToolResult(False, error=str(exc))

        ok = proc.returncode == 0
        data = {
            "stdout": proc.stdout,
            "stderr": proc.stderr,
            "returncode": proc.returncode,
        }
        return ToolResult(
            ok=ok,
            data=data,

from __future__ import annotations

import logging
from typing import Any

from om_ai.actions.base import Tool, ToolResult

logger = logging.getLogger(__name__)


class KnowledgeSearchTool(Tool):
    """Search the knowledge base for relevant documents."""

    name = "knowledge.search"
    description = (
        "Search the private knowledge base for relevant context. "
        "Returns matching text chunks with metadata."
    )
    risk_level = "low"
    input_schema = {
        "type": "object",
        "properties": {
            "query": {"type": "string"},
            "k": {"type": "integer"},
        },
        "required": ["query"],
    }

    def __init__(self, knowledge_base: Any, default_k: int = 5, tenant_id: str = "default") -> None:
        self._kb = knowledge_base
        self._default_k = default_k
        self._tenant_id = tenant_id

    def run(self, query: str = "", k: int | None = None, tenant_id: str | None = None, **kwargs: Any) -> ToolResult:
        q = query or kwargs.get("q") or ""
        if not q:
            return ToolResult(False, error="query is required")
        top_k = k if k is not None else self._default_k
        tid = tenant_id or self._tenant_id
        try:
            if hasattr(self._kb, "search_compat"):
                results = self._kb.search_compat(q, k=top_k, tenant_id=tid)
            else:
                # PersistentKnowledgeBase.search(query, tenant_id, k=...)
                try:
                    results = self._kb.search(q, tid, k=top_k)
                except TypeError:
                    results = self._kb.search(q, top_k)
            snippets = []
            for r in results or []:
                if hasattr(r, "text"):
                    snippets.append({
                        "text": r.text,
                        "doc_id": getattr(r, "doc_id", None),
                        "score": getattr(r, "score", None),
                        "tenant_id": getattr(r, "tenant_id", tid),
                    })
                elif isinstance(r, dict):
                    snippets.append(r)
                else:
                    snippets.append({"text": str(r)})
            return ToolResult(ok=True, data=snippets)
        except Exception as exc:
            logger.warning("KnowledgeSearchTool error: %s", exc)
            return ToolResult(ok=False, error=str(exc))

"""Detect weak areas from evaluation scores."""
from __future__ import annotations

from typing import Any


THRESHOLDS = {
    "structure": 70.0,
    "clarity": 65.0,
    "security": 70.0,
    "task_fit": 65.0,
    "code_quality": 70.0,
}


def detect_weaknesses(eval_result: dict[str, Any]) -> list[dict[str, Any]]:
    scores = eval_result.get("scores") or {}
    weak: list[dict[str, Any]] = []
    for key, thr in THRESHOLDS.items():
        val = float(scores.get(key, 100.0))
        if val < thr:
            weak.append(
                {
                    "area": key,
                    "score": val,
                    "threshold": thr,
                    "hint": _hint(key),
                }
            )
    if float(eval_result.get("overall") or 0) < 70:
        weak.append(
            {
                "area": "overall",
                "score": float(eval_result.get("overall") or 0),
                "threshold": 70.0,
                "hint": "Improve completeness and directness of the answer",
            }
        )
    # dedupe by area
    seen: set[str] = set()
    out: list[dict[str, Any]] = []
    for w in weak:
        if w["area"] in seen:
            continue
        seen.add(w["area"])
        out.append(w)
    return out


def _hint(area: str) -> str:
    return {
        "structure": "Use clear sections: Understanding, Plan, Implementation, Validation",
        "clarity": "Write shorter clear sentences; avoid garbled fragments",
        "security": "Include validation, no secrets, safe auth patterns",
        "task_fit": "Address every part of the user ask explicitly",
        "code_quality": "Include runnable code blocks and tests",
    }.get(area, "Improve this dimension")

