"""
OM-1.0 Self Evaluation Engine

Checks generated answers before
sending to the user.
"""


class SelfEvaluator:


    def __init__(self):

        self.minimum_score = 0.7



    def evaluate(
        self,
        question: str,
        answer: str,
        technology: dict | None = None
    ):


        score = 1.0

        issues = []


        question_lower = question.lower()

        answer_lower = answer.lower()


        # --------------------------------
        # Check answer length
        # --------------------------------

        if len(answer.strip()) < 50:

            score -= 0.3

            issues.append(
                "Answer is too short"
            )


        # --------------------------------
        # Technology validation (coding only)
        # --------------------------------

        coding_ask = False
        try:
            from om_ai.understanding.query_kind import is_coding_task

            coding_ask = is_coding_task(question)
        except Exception:
            coding_ask = False

        if technology and coding_ask:

            expected = technology.get(
                "technology"
            )


            if expected:

                phrase = expected.lower()
                tokens = [t for t in phrase.split() if t]
                matched = phrase in answer_lower or (
                    len(tokens) > 1 and all(t in answer_lower for t in tokens)
                )
                if not matched:

                    score -= 0.3

                    issues.append(
                        f"Missing technology: {expected}"
                    )


        # --------------------------------
        # Requirement validation
        # --------------------------------

        important_words = [

            word

            for word in question_lower.split()

            if len(word) > 4

        ]


        missing = []


        for word in important_words:

            if word not in answer_lower:

                missing.append(word)


        if len(missing) > 3:

            score -= 0.2

            issues.append(
                "Some requested items may be missing"
            )


        approved = (
            score >= self.minimum_score
        )


        return {

            "approved": approved,

            "score": round(
                max(score,0),
                2
            ),

            "issues": issues,

            "improvement_needed":
            not approved

        }

"""
OM Knowledge Confidence Engine

Checks:

- Retrieval quality
- Source quality
- Context availability
- Answer confidence
"""


from __future__ import annotations


from dataclasses import dataclass

from typing import Any



@dataclass
class KnowledgeConfidence:


    score: float

    confidence: str

    reasons: list[str]

    retry_needed: bool




class KnowledgeConfidenceEngine:



    def evaluate(
        self,
        question: str,
        knowledge: list[dict[str, Any]] | None
    ) -> KnowledgeConfidence:


        reasons = []


        if not knowledge:

            return KnowledgeConfidence(

                score=0.0,

                confidence="low",

                reasons=[
                    "no knowledge retrieved"
                ],

                retry_needed=True

            )



        scores = []


        for item in knowledge:


            score = float(

                item.get(
                    "hybrid_score",

                    item.get(
                        "score",
                        0
                    )

                )

                or 0

            )


            scores.append(score)



        best = max(
            scores
        )



        if best >= 0.80:


            level = "high"


            reasons.append(
                "strong knowledge match"
            )


        elif best >= 0.50:


            level="medium"


            reasons.append(
                "partial knowledge match"
            )


        else:


            level="low"


            reasons.append(
                "weak knowledge match"
            )



        retry = best < 0.40



        return KnowledgeConfidence(

            score=round(
                best,
                3
            ),

            confidence=level,

            reasons=reasons,

            retry_needed=retry

        )

