        self.kb = PersistentKnowledgeBase()
        self.corpus_root = Path(corpus_root or "data/om-knowledge-universe-v1/knowledge")

    def upload_path(self, path: str | Path, *, domain: str | None = None) -> dict[str, Any]:
        path = Path(path)
        run_root = Path("data/om-foundation-corpus")
        info = ingest_file(path, out_root=run_root)
        meta = dict(info["metadata"])
        if domain:
            meta["domain"] = domain
        doc_id = self.kb.ingest_file(path, self.tenant_id, metadata=meta)
        try:
            from om_ai.knowledge.embeddings import EmbeddingIndex

            body = path.read_text(encoding="utf-8", errors="ignore")[:8000]
            EmbeddingIndex().upsert(
                body,
                tenant_id=self.tenant_id,
                metadata=meta,
                doc_id=str(doc_id),
            )
        except Exception:
            pass
        return {"doc_id": doc_id, "ingestion": info}

    def search(self, query: str, *, k: int = 5) -> list[dict[str, Any]]:
        hits = self.kb.search(query, self.tenant_id, k=k)
        out: list[dict[str, Any]] = []
        seen: set[str] = set()
        for h in hits or []:
            if hasattr(h, "text"):
                text = str(h.text)[:500]
                row = {
                    "text": text,
                    "score": float(getattr(h, "score", 0.0) or 0.0),
                    "doc_id": getattr(h, "doc_id", ""),
                    "metadata": getattr(h, "metadata", {}) or {},
                }
            elif isinstance(h, dict):
                row = h
                text = str(row.get("text") or "")
            else:
                continue
            key = text[:120]
            if key in seen:
                continue
            seen.add(key)
            out.append(row)
        try:
            from om_ai.knowledge.embeddings import EmbeddingIndex

            for row in EmbeddingIndex().search(query, tenant_id=self.tenant_id, k=k):
                text = str(row.get("text") or "")[:500]
                key = text[:120]
                if not text or key in seen:
                    continue
                seen.add(key)
                out.append(
                    {
                        "text": text,
                        "score": float(row.get("score") or 0.0),
                        "doc_id": row.get("id") or "",
                        "metadata": row.get("metadata") or {},
                    }
                )
        except Exception:
            pass
        out.sort(key=lambda r: float(r.get("score") or 0.0), reverse=True)
        return out[:k]


def search_knowledge(query: str, *, tenant_id: str = "default", k: int = 5) -> list[dict[str, Any]]:
    return VectorKnowledgeLayer(tenant_id=tenant_id).search(query, k=k)


def upload_document(path: str, *, tenant_id: str = "default", domain: str | None = None) -> dict[str, Any]:
    return VectorKnowledgeLayer(tenant_id=tenant_id).upload_path(path, domain=domain)

"""
OM Quality Checker

Evaluates generated results.
"""


from __future__ import annotations




class QualityChecker:



    def evaluate(

        self,

        result:str

    ) -> dict:



        score = 0.0


        issues=[]



        if result:

            score += 0.4


        else:

            issues.append(
                "empty response"
            )



        if len(result) > 100:

            score +=0.2


        else:

            issues.append(
                "response too short"
            )



        if "solution" in result.lower():

            score +=0.2



        if "error" not in result.lower():

            score +=0.2



        return {


            "score":

                round(score,2),


            "approved":

                score >=0.7,


            "issues":

                issues

        }

"""
OM Self Correction Loop
"""


from .quality_checker import QualityChecker

from .correction import CorrectionPlanner





class SelfCorrectionLoop:



    def __init__(self):


        self.checker = QualityChecker()

        self.corrector = CorrectionPlanner()




    def review(

        self,

        result:str

    ):


        evaluation = self.checker.evaluate(

            result

        )



        if evaluation["approved"]:


            return {


                "approved":

                    True,


                "evaluation":

                    evaluation,


                "actions":[]

            }




        actions = self.corrector.create(

            evaluation

        )



        return {


            "approved":

                False,


            "evaluation":

                evaluation,


            "actions":

                actions

        }

"""
OM Correction Planner

Creates improvement actions.
"""




class CorrectionPlanner:



    def create(

        self,

        evaluation:dict

    ) -> list[str]:


        actions=[]



        for issue in evaluation.get(
            "issues",
            []
        ):


            if "empty" in issue:

                actions.append(
                    "Generate complete response"
                )


            if "short" in issue:

                actions.append(
                    "Add more explanation"
                )



        if not actions:

            actions.append(
                "Improve reasoning quality"
            )



        return actions

