class DatasetProblemDetector:



    def detect(
        self,
        item:dict
    ) -> list[str]:


        problems=[]


        instruction = item.get(
            "instruction",
            ""
        )


        response = item.get(
            "response",
            ""
        )



        if not instruction.strip():

            problems.append(
                "missing_instruction"
            )


        if not response.strip():

            problems.append(
                "missing_response"
            )


        if len(response.split()) < 5:

            problems.append(
                "short_answer"
            )


        if "error" in response.lower():

            problems.append(
                "contains_error"
            )


        return problems

"""
OM Automated Dataset Improvement Agent
"""


from .detector import DatasetProblemDetector

from .rewriter import SampleRewriter

from .history import ImprovementHistory





class DatasetImprovementAgent:



    def __init__(self):


        self.detector = DatasetProblemDetector()

        self.rewriter = SampleRewriter()

        self.history = ImprovementHistory()




    def improve(
        self,
        dataset:list[dict]
    ):



        improved=[]



        for item in dataset:


            problems = self.detector.detect(
                item
            )



            if problems:


                new_item = self.rewriter.rewrite(

                    item,

                    problems

                )


                self.history.save(
                    new_item
                )


                improved.append(
                    new_item
                )


            else:


                improved.append(
                    item
                )



        return {


            "input":

                len(dataset),


            "improved":

                len(improved),


            "dataset":

                improved

        }

