from dataclasses import dataclass, field



@dataclass
class AgentCapability:


    name: str


    skills: list[str] = field(
        default_factory=list
    )


    domains: list[str] = field(
        default_factory=list
    )


    priority: float = 1.0



    def matches(self, task:str):

        text = task.lower()

