def clean_user_response(text: str) -> str:

    """
    Remove internal AI reasoning sections.
    """

    remove_sections = [

        "## Analysis",

        "## Technology",

        "## Architecture",

        "## Evaluation",

        "## Self-critique",

        "## Weak areas",

    ]


    for section in remove_sections:

        index = text.find(section)


        if index != -1:

            text = text[:index]


    return text.strip()

_LEAK = re.compile(
    r"(?i)(\bintent\s*:|\bagents\s*:|\bdomain\s*:|self-critique|self critique|"
    r"knowledge context|reflectionengine|pipeline trace|\bscore\s*:|"
    r"dataset_id|training.hints|\*\*ask:\*\*|^\*\*understanding:\*\*|"
    r"no strong corpus match yet|om-ai brain power|"
    r"heuristic foundation path|passed:\s*true|"
    r"domain\s*`|intent\s*`)"
)

_PIPELINE_HEADINGS = re.compile(
    r"(?im)^#{1,3}\s+(understanding|analysis|technology|architecture|plan|"
    r"validation|evaluation|self-critique|weak areas|knowledge context|"
    r"implementation|next)\b"
)

_PIPELINE_DUMP = re.compile(
    r"(?is)(\*\*ask:\*\*|\*\*understanding:\*\*|##\s+analysis\b|\bagents\s*:|"
    r"self-critique|no strong corpus match yet|om-ai brain power|"
    r"heuristic foundation path|##\s+evaluation\b|##\s+validation\b|"
    r"passed:\s*true|score:\s*0\.|confidence:\s*0\.|"
    r"##\s+knowledge brain|##\s+connected systems|##\s+cross-lingual|"
    r"##\s+memory\b|\[layered\]|\[decision\]|\[workflow\]|"
    r"om ai foundation sample|physics mechanics energy)"
)


def looks_like_pipeline_dump(text: str) -> bool:
    s = text or ""
    if _PIPELINE_DUMP.search(s):
        return True
    hits = len(_PIPELINE_HEADINGS.findall(s))
    return hits >= 3


def ensure_public_reply(
    question: str,
    text: str,
    payload: dict[str, Any] | None = None,
) -> str:
    """Last-mile gate: never show internal brain chrome to a normal user.

    Does NOT invent canned coding/business templates when content is missing —
    prefers facts/brain, then stripped text, then empty (so chat can fall through).
    """
    if response_mode() == "developer":
        return (text or "").strip()
    fmt = ResponseFormatter()
    data = {**(payload or {}), "question": question, "answer": text or ""}
    raw = (text or "").strip()

    # Prefer existing intelligence answer if real
    intel = data.get("intelligence") if isinstance(data.get("intelligence"), dict) else {}
    intel_answer = str(intel.get("answer") or "").strip()
    if intel_answer and not looks_like_pipeline_dump(intel_answer):
        try:
            from om_ai.core.intelligence.real_answer import looks_like_static_reply

            if not looks_like_static_reply(intel_answer):
                return clean_user_response(intel_answer).strip() + "\n"
        except Exception:
            return clean_user_response(intel_answer).strip() + "\n"

    if raw and not looks_like_pipeline_dump(raw):
        out = fmt._strip_leaks(raw)
        try:
            from om_ai.core.intelligence.real_answer import looks_like_static_reply

            if looks_like_static_reply(out):
                out = ""
        except Exception:
            pass
        if out.strip():
            return out.strip() + "\n"

    # Try facts / brain before any template
    try:
        from om_ai.core.intelligence.real_answer import build_real_answer

        real = build_real_answer(question)
        if real:
            return real.strip() + "\n"
    except Exception:
        pass

    curated = fmt._direct_answer(question, data)
    if curated and not looks_like_pipeline_dump(curated):
        try:
            from om_ai.core.intelligence.real_answer import looks_like_static_reply

            if not looks_like_static_reply(curated) and len(curated.strip()) > 20:
                return curated.strip() + "\n"
        except Exception:
            if len(curated.strip()) > 20:
                return curated.strip() + "\n"
    # Empty → recover with dataset/reasoning fallback (never blank UI)
    try:
        from om_ai.agent.verifier import compose_fallback

        intent_name = ""
        intent = (payload or {}).get("intent") if isinstance(payload, dict) else {}
        if isinstance(intent, dict):
            intent_name = str(intent.get("intent") or "")
        fb = compose_fallback(intent=intent_name or "chat", user_text=question)
        if fb and fb.strip():
            return fb.strip() + "\n"
    except Exception:
        pass
    return "Hello — I’m OM. How can I help you?\n"


