def _extract_prompt_topic(q: str) -> str:
    topic = (q or "").strip()
    for noise in (
        "create prompt for",
        "make prompt for",
        "write prompt for",
        "generate prompt for",
        "create a prompt for",
        "create prompt",
        "make prompt",
        "write prompt",
        "generate prompt",
    ):
        if noise in topic.lower():
